<?php
function act(string $action,array $p): string {
    switch($action){
    case 'logout':$_SESSION=[];session_destroy();return 'login.php';
    case 'master_save':$m=(string)($p['module']??'');saveMaster($m,$p);return '?page='.$m;
    case 'master_delete':$m=(string)($p['module']??'');deleteMaster($m,integer($p['id']??0));return '?page='.$m;
    case 'daily_save':saveDaily($p);return '?page=daily-menu';
    case 'daily_delete':need(['Owner']);$id=integer($p['id']??0);tx(function()use($id){$old=one('SELECT * FROM daily_menu_items WHERE daily_menu_item_id=? AND menu_date=?',[$id,today()]);if(!$old)throw new RuntimeException('Only today’s unused listings can be removed.');q('DELETE FROM daily_menu_items WHERE daily_menu_item_id=?',[$id]);audit('daily_listing_removed','daily_menu_items',$id,$old);});return '?page=daily-menu';
    case 'combo_add':need(['Owner']);tx(function()use($p){$parent=integer($p['combo_menu_item_id']??0);$child=integer($p['component_menu_item_id']??0);$qty=integer($p['quantity']??0,1,100);if(!val("SELECT COUNT(*) FROM menu_items WHERE menu_item_id=? AND item_type='combo'",[$parent])||!val("SELECT COUNT(*) FROM menu_items WHERE menu_item_id=? AND item_type<>'combo' AND is_active=1",[$child]))throw new RuntimeException('Choose a combo and a non-combo component.');$old=one('SELECT * FROM combo_components WHERE combo_menu_item_id=? AND component_menu_item_id=?',[$parent,$child]);if($old){$id=(int)$old['combo_component_id'];change('combo_components','combo_component_id',$id,['quantity'=>$qty]);}else $id=insert('combo_components',['combo_menu_item_id'=>$parent,'component_menu_item_id'=>$child,'quantity'=>$qty]);audit('combo_component_saved','combo_components',$id,$old,['quantity'=>$qty]);});return '?page=combos';
    case 'combo_delete':need(['Owner']);$id=integer($p['id']??0);tx(function()use($id){q('DELETE FROM combo_components WHERE combo_component_id=?',[$id]);audit('combo_component_removed','combo_components',$id);});return '?page=combos';
    case 'session_open':$u=need(['Owner','Cashier']);$float=dec(cents($p['opening_float']??''));tx(function()use($u,$float){if(openSession(false))throw new RuntimeException('A cash drawer is already open. Close it before opening another.');$id=insert('cash_sessions',['user_id'=>$u['user_id'],'opened_at'=>now(),'opening_float'=>$float,'status'=>'open']);audit('cash_session_opened','cash_sessions',$id);});return '?page=cash-session';
    case 'session_close':$u=need(['Owner','Cashier']);$id=integer($p['id']??0);$count=cents($p['counted_cash']??'');tx(function()use($u,$id,$count){$s=one("SELECT * FROM cash_sessions WHERE cash_session_id=? AND status='open'",[$id]);if(!$s||(int)$s['user_id']!==(int)$u['user_id'])throw new RuntimeException('You can only close your own open session.');$totals=sessionTotals($id);change('cash_sessions','cash_session_id',$id,['counted_cash'=>dec($count),'closed_at'=>now(),'status'=>'closed']);audit('cash_session_closed','cash_sessions',$id,null,['expected'=>dec($totals['expected']),'counted'=>dec($count)]);});return '?page=cash-session';
    case 'checkout':$cart=json_decode((string)($p['cart']??''),true);if(!is_array($cart))throw new InvalidArgumentException('Invalid cart.');$id=checkout($cart,(string)($p['order_type']??''),$p['cash_tendered']??'',(string)($p['operation_token']??''));return '?page=sale&id='.$id;
    case 'refill':refill(integer($p['id']??0),(string)($p['operation_token']??''));return '?page=refills';
    case 'visit_close':$u=need();$id=integer($p['id']??0);tx(function()use($id,$u){$l=one('SELECT * FROM sale_items WHERE sale_item_id=? AND unli_rice_granted=1',[$id]);if(!$l)throw new RuntimeException('Eligible meal not found.');if(!$l['refill_closed_at']){change('sale_items','sale_item_id',$id,['refill_closed_at'=>now(),'refill_closed_by'=>$u['user_id']]);audit('visit_closed','sale_items',$id);}});return '?page=refills';
    case 'stock_move':stockMove($p);return '?page=movements';
    case 'receipt_create':$u=need(['Owner','Staff']);$key=operation($p['operation_token']??'');$id=tx(function()use($p,$u,$key){$old=val('SELECT stock_receipt_id FROM stock_receipts WHERE receipt_token=?',[$key]);if($old)return (int)$old;$supplier=integer($p['supplier_id']??0);if(!val('SELECT COUNT(*) FROM suppliers WHERE supplier_id=? AND is_active=1',[$supplier]))throw new RuntimeException('Choose an active supplier.');[$source,$session]=validatePaymentSource($p);$id=insert('stock_receipts',['receipt_token'=>$key,'supplier_id'=>$supplier,'received_by'=>$u['user_id'],'received_at'=>now(),'reference_number'=>trim((string)($p['reference_number']??''))?:null,'payment_source'=>$source,'cash_session_id'=>$session,'status'=>'draft']);audit('receipt_draft_created','stock_receipts',$id);return $id;});return '?page=receipt&id='.$id;
    case 'receipt_line':need(['Owner','Staff']);$id=integer($p['id']??0);tx(function()use($p,$id){if(!val("SELECT COUNT(*) FROM stock_receipts WHERE stock_receipt_id=? AND status='draft'",[$id]))throw new RuntimeException('Only draft receipts can be edited.');$item=integer($p['inventory_item_id']??0);if(!val('SELECT COUNT(*) FROM inventory_items WHERE inventory_item_id=? AND is_active=1',[$item]))throw new RuntimeException('Choose an active ingredient.');$qty=fixed($p['quantity']??'');if(!$qty)throw new RuntimeException('Quantity must be positive.');$data=['quantity'=>dec($qty,3),'unit_cost'=>dec(cents($p['unit_cost']??''))];$old=one('SELECT * FROM stock_receipt_items WHERE stock_receipt_id=? AND inventory_item_id=?',[$id,$item]);if($old)change('stock_receipt_items','stock_receipt_item_id',(int)$old['stock_receipt_item_id'],$data);else insert('stock_receipt_items',['stock_receipt_id'=>$id,'inventory_item_id'=>$item,...$data]);audit('receipt_line_saved','stock_receipts',$id);});return '?page=receipt&id='.$id;
    case 'receipt_line_delete':need(['Owner','Staff']);$id=integer($p['id']??0);tx(function()use($p,$id){if(!val("SELECT COUNT(*) FROM stock_receipts WHERE stock_receipt_id=? AND status='draft'",[$id]))throw new RuntimeException('Posted receipt cannot change.');q('DELETE FROM stock_receipt_items WHERE stock_receipt_item_id=? AND stock_receipt_id=?',[integer($p['line_id']??0),$id]);audit('receipt_line_removed','stock_receipts',$id);});return '?page=receipt&id='.$id;
    case 'receipt_post':$id=integer($p['id']??0);postReceipt($id);return '?page=receipt&id='.$id;
    case 'receipt_delete':need(['Owner','Staff']);$id=integer($p['id']??0);tx(function()use($id){if(!val("SELECT COUNT(*) FROM stock_receipts WHERE stock_receipt_id=? AND status='draft'",[$id]))throw new RuntimeException('Only a draft can be deleted.');q('DELETE FROM stock_receipt_items WHERE stock_receipt_id=?',[$id]);q('DELETE FROM stock_receipts WHERE stock_receipt_id=?',[$id]);audit('receipt_draft_deleted','stock_receipts',$id);});return '?page=receiving';
    case 'expense_add':$u=need(['Owner']);$key=operation($p['operation_token']??'');tx(function()use($p,$u,$key){if(val('SELECT COUNT(*) FROM expenses WHERE operation_token=?',[$key]))return;[$source,$session]=validatePaymentSource($p);$amount=cents($p['amount']??'');if(!$amount)throw new RuntimeException('Expense must be greater than zero.');$category=integer($p['expense_category_id']??0);if(!val('SELECT COUNT(*) FROM expense_categories WHERE expense_category_id=? AND is_active=1',[$category]))throw new RuntimeException('Choose an active category.');$id=insert('expenses',['expense_category_id'=>$category,'amount'=>dec($amount),'paid_at'=>now(),'description'=>textval($p['description']??''),'payment_source'=>$source,'cash_session_id'=>$session,'operation_token'=>$key,'recorded_by'=>$u['user_id']]);audit('expense_posted','expenses',$id);});return '?page=expenses';
    case 'profile_save':$u=need();$name=textval($p['full_name']??'',100);if(!password_verify((string)($p['current_password']??''),$u['password_hash']))throw new RuntimeException('Your current password is incorrect.');$data=['full_name'=>$name];if(($p['password']??'')!==''){if(strlen($p['password'])<10||strlen($p['password'])>72)throw new RuntimeException('New password must be 10 to 72 characters.');$data['password_hash']=password_hash($p['password'],PASSWORD_DEFAULT);}tx(function()use($u,$data){change('users','user_id',(int)$u['user_id'],$data);audit('profile_updated','users',(int)$u['user_id']);});if(isset($data['password_hash'])){session_regenerate_id(true);$_SESSION['auth_stamp']=hash('sha256',$data['password_hash']);}return '?page=profile';
    default:throw new RuntimeException('Unknown action.');
    }
}
